const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });

  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(140.878144, 27.245974);
  const buffer_radius_km = 2;
  const region = point.buffer(buffer_radius_km * 1000); // 2 km radius
  const date = '2014-03-30';
  const scale = 30; // Landsat resolution

  // 2. Data Acquisition & Check
  let imageCollection = ee.ImageCollection('LANDSAT/LC08/C01/T1_SR')
    .filterBounds(region)
    .filterDate(date, ee.Date(date).advance(1, 'day'));

  if (imageCollection.size().getInfo() === 0) {
    console.log("No Landsat 8 images found for the specified date and location.");
    console.log("C1");
    return;
  }

  // Select the least cloudy image within the single day.
  const image = ee.Image(imageCollection.sort('CLOUD_COVER').first());

  if (image === null) {
    console.log("No valid image found after sorting for cloud cover.");
    console.log("C1"); // Technically, an image might exist but first() returns null if collection is empty after sort.
    return;
  }

  const cloudCover = image.get('CLOUD_COVER').getInfo();
  console.log(`Image acquired: ${image.id().getInfo()}, Cloud Cover: ${cloudCover.toFixed(2)}%`);

  // Cloud masking using QA_PIXEL band (CFMask)
  // Bits 3 and 5 are cloud shadow and cloud, respectively.
  // Bits 1 and 4 are dilated cloud and cirrus, respectively (useful to include for strict masking).
  const qa = image.select('pixel_qa');
  const cloudBitMask = 1 << 5; // Cloud
  const cloudShadowBitMask = 1 << 3; // Cloud Shadow
  const cirrusBitMask = 1 << 4; // Cirrus (Landsat 8)
  const dilatedCloudBitMask = 1 << 1; // Dilated Cloud

  const mask = qa.bitwiseAnd(cloudBitMask)
    .eq(0)
    .and(qa.bitwiseAnd(cloudShadowBitMask).eq(0))
    .and(qa.bitwiseAnd(cirrusBitMask).eq(0))
    .and(qa.bitwiseAnd(dilatedCloudBitMask).eq(0));

  const maskedImage = image.updateMask(mask);

  // Calculate NDWI for water detection (NIR - SWIR1) / (NIR + SWIR1)
  // Landsat 8 bands: B5 (NIR), B6 (SWIR1)
  const ndwi = maskedImage.normalizedDifference(['B5', 'B6']).rename('NDWI');

  // Create a land mask: NDWI values less than a threshold (e.g., 0) indicate land.
  // The threshold might need adjustment based on the specific environment.
  // For highly isolated islands, a stricter water mask is often better.
  const landMask = ndwi.lt(0.0); // Adjust threshold if needed

  // Get the land pixels within the region of interest
  const landPixels = landMask.updateMask(landMask).clip(region);

  // 3. Processing: Check for valid pixels after masking
  const totalLandPixels = landPixels.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  }).get('NDWI').getInfo(); // Band name will be 'NDWI' due to rename

  if (totalLandPixels === 0 || totalLandPixels === null) {
    console.log("No valid land pixels found within the region after cloud and water masking.");
    console.log("C2");
    return;
  }
  console.log(`Total land pixels within region: ${totalLandPixels}`);

  // 4. Calculation: Identify and count connected components (islands)
  // Use connectedComponents to label distinct land masses.
  // The 'landPixels' image now has 1 for land and 0 for water (or masked).
  const connectedComponents = landPixels.connectedComponents({
    connectedness: 8, // 8-way connectivity
    maxSize: 1024 // Max number of pixels in a component to label (default is 100) - for noise reduction
  });

  // Get the unique labels (island IDs) within the region.
  // Filter out the background (label 0) if it exists, or small noise components.
  // The reduceRegion will count unique values.
  const islandLabels = connectedComponents.reduceRegion({
    reducer: ee.Reducer.frequencyHistogram(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  if (islandLabels === null) {
    console.log("Failed to calculate island labels.");
    console.log("C3");
    return;
  }

  // Count distinct labels, excluding the background (label 0).
  let islandCount = 0;
  for (const label in islandLabels) {
    if (label !== '0') { // Label 0 is usually background (water/masked areas)
      islandCount++;
    }
  }

  console.log(`Number of isolated land masses (islands) found: ${islandCount}`);

  // 5. Validation & Final Answer
  if (islandCount === 2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

initEE();
